static boolean armstrong(int n) {
    if (n < 0) return false;
    int d = 0, x = n;
    do { d++; x /= 10; } while (x > 0);
    long sum = 0; x = n;
    do {
        int digit = x % 10;
        long power = 1;
        for (int i = 0; i < d; i++) power *= digit;
        sum += power; x /= 10;
    } while (x > 0);
    return sum == n;
}

