static List<Integer> divisors(int n) {
    if (n <= 0) throw new IllegalArgumentException();
    List<Integer> small = new ArrayList<>(), large = new ArrayList<>();
    for (int i = 1; i <= n / i; i++) {
        if (n % i != 0) continue;
        small.add(i);
        if (i != n / i) large.add(n / i);
    }
    for (int i = large.size() - 1; i >= 0; i--) small.add(large.get(i));
    return small;
}

