static int[] extremes(int[] a) {
    if (a.length == 0) throw new IllegalArgumentException();
    Map<Integer, Integer> count = new HashMap<>();
    for (int x : a) count.merge(x, 1, Integer::sum);
    int high = a[0], low = a[0];
    for (int x : count.keySet()) {
        if (count.get(x) > count.get(high) || (count.get(x).equals(count.get(high)) && x < high)) high = x;
        if (count.get(x) < count.get(low) || (count.get(x).equals(count.get(low)) && x < low)) low = x;
    }
    return new int[]{high, low};
}
